INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:9-1','Classic shakshuka',ARRAY['4 eggs','4 ripe tomatoes','1 onion','1 red pepper','2 cloves garlic','2 tbsp olive oil','2 tbsp tomato paste','1 tsp sweet paprika','½ tsp ground cumin','½ tsp salt','¼ tsp black pepper','2 tbsp chopped parsley']::text[],ARRAY['Chop the onion, red pepper, garlic and tomatoes.','Heat the oil in a large frying pan over medium heat. Fry the onion until soft, then add the red pepper and garlic and cook for 2–3 minutes.','Add the tomatoes, tomato paste, paprika, cumin, salt and pepper. Simmer for 10–15 minutes, stirring now and then, until the sauce thickens.','Make 4 hollows in the sauce and crack an egg into each.','Cover and cook over low heat for 5–8 minutes, until the whites are set. Scatter with parsley and serve straight away.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',10,20,'2','chef','Eyal Shani',ARRAY['Breakfast','Middle Eastern','Eggs','Vegetarian','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:9-1','he','שקשוקה קלאסית',ARRAY['4 ביצים','4 עגבניות בשלות','1 בצל','1 פלפל אדום','2 שיני שום','2 כפות שמן זית','2 כפות רסק עגבניות','1 כפית פפריקה מתוקה','½ כפית כמון','½ כפית מלח','¼ כפית פלפל שחור','2 כפות פטרוזיליה קצוצה']::text[],ARRAY['קוצצים את הבצל, הפלפל האדום, השום והעגבניות.','מחממים את השמן במחבת גדולה על אש בינונית. מטגנים את הבצל עד שהוא מתרכך, מוסיפים את הפלפל והשום ומבשלים 2–3 דקות.','מוסיפים את העגבניות, רסק העגבניות, הפפריקה, הכמון, המלח והפלפל. מבשלים 10–15 דקות, מערבבים מדי פעם, עד שהרוטב מסמיך.','יוצרים 4 גומות ברוטב ושוברים ביצה לכל גומה.','מכסים ומבשלים על אש נמוכה 5–8 דקות, עד שהחלבונים מתייצבים. מפזרים פטרוזיליה ומגישים מיד.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:9-1','ru','Классическая шакшука',ARRAY['4 яйца','4 спелых помидора','1 луковица','1 красный сладкий перец','2 зубчика чеснока','2 ст. л. оливкового масла','2 ст. л. томатной пасты','1 ч. л. сладкой паприки','½ ч. л. молотого кумина','½ ч. л. соли','¼ ч. л. чёрного перца','2 ст. л. рубленой петрушки']::text[],ARRAY['Нарежьте лук, красный перец, чеснок и помидоры.','Разогрейте масло в большой сковороде на среднем огне. Обжарьте лук до мягкости, затем добавьте перец и чеснок и готовьте 2–3 минуты.','Добавьте помидоры, томатную пасту, паприку, кумин, соль и перец. Тушите 10–15 минут, время от времени помешивая, пока соус не загустеет.','Сделайте в соусе 4 углубления и разбейте в каждое по яйцу.','Накройте крышкой и готовьте на слабом огне 5–8 минут, пока белки не схватятся. Посыпьте петрушкой и сразу подавайте.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:11-10','Spanish omelette',ARRAY['4 potatoes','6 eggs','1 onion','3 tbsp oil','½ tsp salt','¼ tsp black pepper','2 tbsp chopped parsley','½ tsp paprika','½ tsp garlic granules','2 spring onions','1 tbsp chopped dill','1 pinch turmeric']::text[],ARRAY['Peel the potatoes and slice them thinly. Slice the onion and the spring onions.','Heat 2 tbsp of the oil in a large frying pan over medium heat. Fry the potatoes and onion for 12–15 minutes, turning often, until the potatoes are soft.','Beat the eggs in a large bowl with the salt, pepper, paprika, garlic granules and turmeric. Stir in the potatoes, onion, spring onions, parsley and dill.','Heat the remaining oil in the pan, pour in the mixture and cook over low heat for 8–10 minutes, until the edges are set.','Carefully turn the omelette over with the help of a plate and cook for 3–4 minutes more, until set in the centre. Serve hot or cold.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',10,25,'4','chef','Eyal Shani',ARRAY['Breakfast','Spanish','Eggs','Potatoes','Vegetarian','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:11-10','he','חביתה ספרדית',ARRAY['4 תפוחי אדמה','6 ביצים','1 בצל','3 כפות שמן','½ כפית מלח','¼ כפית פלפל שחור','2 כפות פטרוזיליה קצוצה','½ כפית פפריקה','½ כפית שום גבישי','2 גבעולי בצל ירוק','1 כף שמיר קצוץ','1 קורט כורכום']::text[],ARRAY['קולפים את תפוחי האדמה ופורסים דק. פורסים את הבצל ואת הבצל הירוק.','מחממים 2 כפות מהשמן במחבת גדולה על אש בינונית. מטגנים את תפוחי האדמה עם הבצל 12–15 דקות, הופכים לעתים קרובות, עד שתפוחי האדמה רכים.','טורפים את הביצים בקערה גדולה עם המלח, הפלפל, הפפריקה, השום הגבישי והכורכום. מוסיפים את תפוחי האדמה, הבצל, הבצל הירוק, הפטרוזיליה והשמיר ומערבבים.','מחממים במחבת את יתרת השמן, יוצקים את התערובת ומבשלים על אש נמוכה 8–10 דקות, עד שהשוליים מתייצבים.','הופכים בזהירות בעזרת צלחת ומבשלים עוד 3–4 דקות, עד שהמרכז מתייצב. מגישים חם או קר.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:11-10','ru','Испанский омлет',ARRAY['4 картофелины','6 яиц','1 луковица','3 ст. л. масла','½ ч. л. соли','¼ ч. л. чёрного перца','2 ст. л. рубленой петрушки','½ ч. л. паприки','½ ч. л. сушёного чеснока','2 стебля зелёного лука','1 ст. л. рубленого укропа','1 щепотка куркумы']::text[],ARRAY['Очистите картофель и тонко нарежьте. Нарежьте репчатый и зелёный лук.','Разогрейте 2 ст. л. масла в большой сковороде на среднем огне. Обжаривайте картофель с луком 12–15 минут, часто переворачивая, пока картофель не станет мягким.','Взбейте яйца в большой миске с солью, перцем, паприкой, сушёным чесноком и куркумой. Вмешайте картофель, лук, зелёный лук, петрушку и укроп.','Разогрейте в сковороде оставшееся масло, вылейте смесь и готовьте на слабом огне 8–10 минут, пока края не схватятся.','Осторожно переверните омлет с помощью тарелки и готовьте ещё 3–4 минуты, пока он не схватится в центре. Подавайте горячим или холодным.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:11-18','Savoury pancakes',ARRAY['1 cup gluten-free flour','1 egg','¾ cup milk','2 tbsp oil','¼ tsp salt','1 pinch black pepper']::text[],ARRAY['Beat the egg in a bowl, then whisk in the milk and oil.','Add the gluten-free flour, salt and pepper and stir just until the batter is smooth; do not overmix. Stir in grated cheese, spring onion or herbs if you like.','Heat a lightly greased frying pan over medium heat and pour in a little batter for each pancake.','Cook until small bubbles appear on top, then turn and cook until golden on both sides. Serve hot.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',5,15,'2','chef','Eyal Shani',ARRAY['Breakfast','International','Eggs','Vegetarian','Gluten-free','Kid friendly']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:11-18','he','פנקייק מלוח',ARRAY['1 כוס קמח ללא גלוטן','1 ביצה','¾ כוס חלב','2 כפות שמן','¼ כפית מלח','1 קורט פלפל שחור']::text[],ARRAY['טורפים את הביצה בקערה ומוסיפים חלב ושמן.','מוסיפים את הקמח ללא גלוטן, המלח והפלפל ומערבבים רק עד לבלילה אחידה, בלי לערבב יותר מדי. אפשר להוסיף גבינה מגוררת, בצל ירוק או עשבי תיבול.','מחממים מחבת משומנת קלות על אש בינונית ויוצקים מעט בלילה לכל פנקייק.','מטגנים עד שמופיעות בועות קטנות, הופכים וממשיכים עד הזהבה משני הצדדים. מגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:11-18','ru','Несладкие оладьи',ARRAY['1 стакан безглютеновой муки','1 яйцо','¾ стакана молока','2 ст. л. масла','¼ ч. л. соли','1 щепотка чёрного перца']::text[],ARRAY['Взбейте яйцо в миске, затем вмешайте молоко и масло.','Добавьте безглютеновую муку, соль и перец и перемешайте только до однородности, не перемешивайте слишком долго. По желанию добавьте тёртый сыр, зелёный лук или зелень.','Разогрейте слегка смазанную маслом сковороду на среднем огне и выливайте понемногу теста на каждую оладью.','Жарьте, пока сверху не появятся маленькие пузырьки, затем переверните и жарьте до золотистого цвета с обеих сторон. Подавайте горячими.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:2-1','Classic chicken soup',ARRAY['4 chicken pieces','2 carrots','2 courgettes','2 celery stalks','1 onion','1 potato','1 handful parsley','2 l water','1 tsp salt','½ tsp black pepper']::text[],ARRAY['Rinse the chicken pieces well. Peel the vegetables and cut them into large pieces. Wash your hands and board after handling raw chicken.','Put the chicken, vegetables and parsley in a large pot and pour in the water. Bring to the boil and skim the foam from the top.','Add the salt and pepper, turn the heat to medium-low and simmer for about 1 hour, until the chicken is very tender and cooked through (74°C).','Taste and adjust the seasoning. Add cooked rice noodles if you like and serve hot.']::text[],NULL,'https://www.facebook.com/groups/749542106307590',20,70,'6','chef','Eyal Shani',ARRAY['Lunch','Soup','Eastern European','Chicken','Potatoes','Gluten-free','Dairy-free','Batch cooking']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:2-1','he','מרק עוף קלאסי',ARRAY['4 חלקי עוף','2 גזרים','2 קישואים','2 גבעולי סלרי','1 בצל','1 תפוח אדמה','1 חופן פטרוזיליה','2 ליטר מים','1 כפית מלח','½ כפית פלפל שחור']::text[],ARRAY['שוטפים היטב את חלקי העוף. קולפים את הירקות וחותכים לחתיכות גדולות. שוטפים ידיים וקרש אחרי מגע בעוף נא.','מניחים את העוף, הירקות והפטרוזיליה בסיר גדול ומוסיפים את המים. מביאים לרתיחה ומסירים את הקצף מלמעלה.','מוסיפים מלח ופלפל, מנמיכים לאש בינונית-נמוכה ומבשלים כשעה, עד שהעוף רך מאוד ומבושל לגמרי (74°C).','טועמים ומתקנים תיבול. מוסיפים אטריות אורז מבושלות אם רוצים ומגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:2-1','ru','Классический куриный суп',ARRAY['4 куска курицы','2 моркови','2 кабачка','2 стебля сельдерея','1 луковица','1 картофелина','1 пучок петрушки','2 л воды','1 ч. л. соли','½ ч. л. чёрного перца']::text[],ARRAY['Хорошо промойте курицу. Очистите овощи и нарежьте крупными кусками. После сырой курицы вымойте руки и доску.','Положите курицу, овощи и петрушку в большую кастрюлю и залейте водой. Доведите до кипения и снимите пену.','Добавьте соль и перец, убавьте огонь до умеренного и варите около часа, пока курица не станет совсем мягкой и полностью проварится (74°C).','Попробуйте и досолите по вкусу. По желанию добавьте отварную рисовую лапшу и подавайте горячим.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:2-2','Garden vegetable soup',ARRAY['2 carrots','2 courgettes','1 potato','1 onion','2 celery stalks','1 tomato','1 handful parsley','2 l water','1 tbsp oil','1 tsp salt','½ tsp black pepper']::text[],ARRAY['Wash the vegetables, peel them as needed and cut into cubes. Chop the parsley.','Heat the oil in a large pot and fry the onion lightly. Add the remaining vegetables and stir for a few minutes.','Pour in the water, add the parsley, salt and pepper and bring to the boil. Simmer for 25–30 minutes, until the vegetables are soft.','Taste, adjust the seasoning and serve hot. For a thicker soup, blend part of it.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',15,30,'6','chef','Eyal Shani',ARRAY['Lunch','Soup','International','Potatoes','Vegetarian','Vegan','Gluten-free','Dairy-free','Budget']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:2-2','he','מרק ירקות עשיר',ARRAY['2 גזרים','2 קישואים','1 תפוח אדמה','1 בצל','2 גבעולי סלרי','1 עגבנייה','1 חופן פטרוזיליה','2 ליטר מים','1 כף שמן','1 כפית מלח','½ כפית פלפל שחור']::text[],ARRAY['שוטפים היטב את הירקות, קולפים לפי הצורך וחותכים לקוביות. קוצצים את הפטרוזיליה.','מחממים את השמן בסיר גדול ומטגנים את הבצל קלות. מוסיפים את שאר הירקות ומערבבים כמה דקות.','מוסיפים את המים, הפטרוזיליה, המלח והפלפל ומביאים לרתיחה. מבשלים 25–30 דקות, עד שהירקות רכים.','טועמים, מתקנים תיבול ומגישים חם. למרק סמיך יותר טוחנים חלק ממנו.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:2-2','ru','Овощной суп',ARRAY['2 моркови','2 кабачка','1 картофелина','1 луковица','2 стебля сельдерея','1 помидор','1 пучок петрушки','2 л воды','1 ст. л. масла','1 ч. л. соли','½ ч. л. чёрного перца']::text[],ARRAY['Вымойте овощи, при необходимости очистите и нарежьте кубиками. Порубите петрушку.','Разогрейте масло в большой кастрюле и слегка обжарьте лук. Добавьте остальные овощи и помешивайте несколько минут.','Влейте воду, добавьте петрушку, соль и перец и доведите до кипения. Варите 25–30 минут, пока овощи не станут мягкими.','Попробуйте, досолите по вкусу и подавайте горячим. Для более густого супа измельчите часть блендером.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:2-3','Red lentil soup',ARRAY['1 cup red lentils','1 onion','2 carrots','1 potato','2 cloves garlic','1 tsp turmeric','6 cups water','1 tbsp oil','1 tsp salt','½ tsp black pepper']::text[],ARRAY['Rinse the lentils well. Chop the onion and garlic and cut the carrots and potato into cubes.','Heat the oil in a large pot and fry the onion and garlic until soft. Add the carrots, potato and lentils.','Pour in the water, add the turmeric, salt and pepper and bring to the boil. Simmer for 25–30 minutes, until everything is completely soft.','Blend as smooth as you like and serve hot, with a squeeze of lemon if you like.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',10,30,'4','chef','Eyal Shani',ARRAY['Lunch','Soup','Middle Eastern','Potatoes','Vegetarian','Vegan','Gluten-free','Dairy-free','Budget']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:2-3','he','מרק עדשים כתומות',ARRAY['1 כוס עדשים כתומות','1 בצל','2 גזרים','1 תפוח אדמה','2 שיני שום','1 כפית כורכום','6 כוסות מים','1 כף שמן','1 כפית מלח','½ כפית פלפל שחור']::text[],ARRAY['שוטפים היטב את העדשים. קוצצים בצל ושום וחותכים את הגזר ותפוח האדמה לקוביות.','מחממים את השמן בסיר גדול ומטגנים את הבצל והשום עד ריכוך. מוסיפים גזר, תפוח אדמה ועדשים.','מוסיפים את המים, הכורכום, המלח והפלפל ומביאים לרתיחה. מבשלים 25–30 דקות, עד ריכוך מלא.','טוחנים לפי המרקם הרצוי ומגישים חם, אפשר עם מעט לימון.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:2-3','ru','Суп из красной чечевицы',ARRAY['1 стакан красной чечевицы','1 луковица','2 моркови','1 картофелина','2 зубчика чеснока','1 ч. л. куркумы','6 стаканов воды','1 ст. л. масла','1 ч. л. соли','½ ч. л. чёрного перца']::text[],ARRAY['Хорошо промойте чечевицу. Порубите лук и чеснок, нарежьте морковь и картофель кубиками.','Разогрейте масло в большой кастрюле и обжарьте лук с чесноком до мягкости. Добавьте морковь, картофель и чечевицу.','Влейте воду, добавьте куркуму, соль и перец и доведите до кипения. Варите 25–30 минут, пока всё не станет совсем мягким.','Измельчите блендером до нужной консистенции и подавайте горячим, по желанию с лимонным соком.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:4-8','Chickpea patties',ARRAY['2 cups cooked chickpeas','1 small onion','2 cloves garlic','3 tbsp gluten-free breadcrumbs','2 tbsp chopped parsley','½ tsp salt','¼ tsp black pepper','4 tbsp oil for frying']::text[],ARRAY['Chop the onion and parsley.','Put the chickpeas, onion and garlic in a food processor. Add the gluten-free breadcrumbs, parsley, salt and pepper and pulse to an even, slightly coarse mixture. If it is too dry, add a little water.','Taste, adjust the seasoning and shape into small patties.','Heat the oil in a frying pan over medium heat. Fry the patties until golden, turn them carefully and fry the other side. Serve hot.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',15,10,'4','chef','Eyal Shani',ARRAY['Lunch','Middle Eastern','Vegetarian','Gluten-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:4-8','he','קציצות חומוס',ARRAY['2 כוסות חומוס מבושל','1 בצל קטן','2 שיני שום','3 כפות פירורי לחם ללא גלוטן','2 כפות פטרוזיליה קצוצה','½ כפית מלח','¼ כפית פלפל שחור','4 כפות שמן לטיגון']::text[],ARRAY['קוצצים את הבצל והפטרוזיליה.','שמים את החומוס, הבצל והשום במעבד מזון. מוסיפים את פירורי הלחם ללא גלוטן, הפטרוזיליה, המלח והפלפל וטוחנים לתערובת אחידה, לא חלקה מדי. אם התערובת יבשה, מוסיפים מעט מים.','טועמים, מתקנים תיבול ויוצרים קציצות קטנות.','מחממים את השמן במחבת על אש בינונית. מטגנים את הקציצות עד הזהבה, הופכים בזהירות ומטגנים את הצד השני. מגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:4-8','ru','Котлеты из нута',ARRAY['2 стакана варёного нута','1 небольшая луковица','2 зубчика чеснока','3 ст. л. безглютеновых панировочных сухарей','2 ст. л. рубленой петрушки','½ ч. л. соли','¼ ч. л. чёрного перца','4 ст. л. масла для жарки']::text[],ARRAY['Порубите лук и петрушку.','Положите нут, лук и чеснок в кухонный комбайн. Добавьте безглютеновые сухари, петрушку, соль и перец и измельчите до однородной, слегка зернистой массы. Если масса суховата, добавьте немного воды.','Попробуйте, досолите по вкусу и сформируйте небольшие котлеты.','Разогрейте масло в сковороде на среднем огне. Обжарьте котлеты до золотистого цвета, осторожно переверните и обжарьте с другой стороны. Подавайте горячими.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:9-6','Vegetable fritters',ARRAY['2 carrots','1 courgette','1 potato','2 eggs','3 tbsp gluten-free flour','½ tsp salt','¼ tsp black pepper','4 tbsp oil for frying']::text[],ARRAY['Grate all the vegetables and squeeze out some of the liquid.','Put the vegetables in a large bowl, add the eggs, gluten-free flour, salt and pepper and mix well.','Heat the oil in a frying pan over medium heat. Drop in spoonfuls of the mixture and flatten them slightly; do not crowd the pan.','Fry until golden, turn and fry the other side until golden and cooked through. Drain on kitchen paper and serve hot.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',15,15,'4','chef','Eyal Shani',ARRAY['Lunch','Middle Eastern','Eggs','Potatoes','Vegetarian','Gluten-free','Dairy-free','Kid friendly']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:9-6','he','לביבות ירק',ARRAY['2 גזרים','1 קישוא','1 תפוח אדמה','2 ביצים','3 כפות קמח ללא גלוטן','½ כפית מלח','¼ כפית פלפל שחור','4 כפות שמן לטיגון']::text[],ARRAY['מגרדים את כל הירקות וסוחטים מעט נוזלים.','מעבירים את הירקות לקערה גדולה, מוסיפים ביצים, קמח ללא גלוטן, מלח ופלפל ומערבבים היטב.','מחממים את השמן במחבת על אש בינונית. יוצרים לביבות בעזרת כף ומשטחים מעט, בלי לצופף במחבת.','מטגנים עד הזהבה, הופכים ומטגנים את הצד השני עד הזהבה ועד שהלביבות מוכנות. מעבירים לנייר סופג ומגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:9-6','ru','Овощные оладьи',ARRAY['2 моркови','1 кабачок','1 картофелина','2 яйца','3 ст. л. безглютеновой муки','½ ч. л. соли','¼ ч. л. чёрного перца','4 ст. л. масла для жарки']::text[],ARRAY['Натрите все овощи на тёрке и слегка отожмите сок.','Переложите овощи в большую миску, добавьте яйца, безглютеновую муку, соль и перец и хорошо перемешайте.','Разогрейте масло в сковороде на среднем огне. Выкладывайте массу ложкой и слегка приплющивайте, не кладите слишком тесно.','Жарьте до золотистого цвета, переверните и жарьте с другой стороны до золотистого цвета и готовности. Обсушите на бумажном полотенце и подавайте горячими.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:5-1','Roast chicken with potatoes',ARRAY['6 chicken pieces','5 potatoes','1 onion','4 tbsp oil','1 tsp salt','½ tsp black pepper','2 tsp paprika']::text[],ARRAY['Heat the oven to 200°C. Peel the potatoes and cut them into chunks. Slice the onion.','Spread the potatoes and onion in a baking dish and lay the chicken pieces on top. Add the oil, salt, pepper and paprika and mix well to coat. Wash your hands after handling raw chicken.','Cover with baking paper or foil and roast for 45 minutes.','Uncover and roast for 20–25 minutes more, until the potatoes are soft, the chicken is browned and its thickest part reaches 74°C. Serve hot.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',20,70,'6','chef','Eyal Shani',ARRAY['Dinner','Mediterranean','Chicken','Potatoes','Gluten-free','Dairy-free','Kid friendly']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-1','he','עוף בתנור עם תפוחי אדמה',ARRAY['6 חלקי עוף','5 תפוחי אדמה','1 בצל','4 כפות שמן','1 כפית מלח','½ כפית פלפל שחור','2 כפיות פפריקה']::text[],ARRAY['מחממים תנור ל-200 מעלות. קולפים את תפוחי האדמה וחותכים לחתיכות. פורסים את הבצל.','מסדרים את תפוחי האדמה והבצל בתבנית ומניחים מעל את חלקי העוף. מוסיפים שמן, מלח, פלפל ופפריקה ומערבבים היטב. שוטפים ידיים אחרי מגע בעוף נא.','מכסים בנייר אפייה או בנייר כסף ואופים 45 דקות.','מסירים את הכיסוי ואופים עוד 20–25 דקות, עד שתפוחי האדמה רכים, העוף משחים והחלק העבה שלו מגיע ל-74°C. מגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-1','ru','Курица с картофелем в духовке',ARRAY['6 кусков курицы','5 картофелин','1 луковица','4 ст. л. масла','1 ч. л. соли','½ ч. л. чёрного перца','2 ч. л. паприки']::text[],ARRAY['Разогрейте духовку до 200°C. Очистите картофель и нарежьте крупными кусками. Нарежьте лук.','Разложите картофель и лук в форме для запекания, сверху выложите курицу. Добавьте масло, соль, перец и паприку и хорошо перемешайте. После сырой курицы вымойте руки.','Накройте пергаментом или фольгой и запекайте 45 минут.','Снимите покрытие и запекайте ещё 20–25 минут, пока картофель не станет мягким, курица не подрумянится и в самой толстой части не достигнет 74°C. Подавайте горячим.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:5-4','One-pot chicken and rice',ARRAY['6 chicken pieces','2 cups rice','1 onion','1 carrot','3 tbsp oil','1 tsp salt','½ tsp black pepper','1 tsp turmeric','3 cups water']::text[],ARRAY['Rinse the rice. Chop the onion and carrot.','Heat the oil in a large pot and fry the onion until soft. Add the carrot, salt, pepper and turmeric.','Add the chicken pieces and brown them on all sides. Wash your hands after handling raw chicken.','Add the rice and the water and bring to the boil. Cover and cook over low heat for 35–40 minutes without lifting the lid, until the rice is tender and the chicken is cooked through (74°C). Serve hot.']::text[],NULL,'https://www.facebook.com/groups/749542106307590',15,45,'6','chef','Eyal Shani',ARRAY['Dinner','Middle Eastern','Chicken','Rice','Gluten-free','Dairy-free','Kid friendly']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-4','he','עוף עם אורז בסיר אחד',ARRAY['6 חלקי עוף','2 כוסות אורז','1 בצל','1 גזר','3 כפות שמן','1 כפית מלח','½ כפית פלפל שחור','1 כפית כורכום','3 כוסות מים']::text[],ARRAY['שוטפים את האורז. קוצצים את הבצל והגזר.','מחממים את השמן בסיר גדול ומטגנים את הבצל עד ריכוך. מוסיפים גזר, מלח, פלפל וכורכום.','מוסיפים את חלקי העוף וצורבים מכל הצדדים. שוטפים ידיים אחרי מגע בעוף נא.','מוסיפים את האורז והמים ומביאים לרתיחה. מכסים ומבשלים על אש נמוכה 35–40 דקות בלי לפתוח את המכסה, עד שהאורז רך והעוף מבושל לגמרי (74°C). מגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-4','ru','Курица с рисом в одной кастрюле',ARRAY['6 кусков курицы','2 стакана риса','1 луковица','1 морковь','3 ст. л. масла','1 ч. л. соли','½ ч. л. чёрного перца','1 ч. л. куркумы','3 стакана воды']::text[],ARRAY['Промойте рис. Порубите лук и морковь.','Разогрейте масло в большой кастрюле и обжарьте лук до мягкости. Добавьте морковь, соль, перец и куркуму.','Добавьте курицу и обжарьте со всех сторон. После сырой курицы вымойте руки.','Добавьте рис и воду и доведите до кипения. Накройте крышкой и готовьте на слабом огне 35–40 минут, не открывая крышку, пока рис не станет мягким, а курица не приготовится полностью (74°C). Подавайте горячим.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:5-6','Coconut curry chicken',ARRAY['6 chicken pieces','1 onion','400 ml canned coconut milk','1 tbsp curry powder','2 cloves garlic','2 tbsp oil','½ tsp salt','¼ tsp black pepper']::text[],ARRAY['Chop the onion and garlic.','Heat the oil in a wide pot and lightly brown the chicken pieces. Add the onion and garlic and stir until soft. Wash your hands after handling raw chicken.','Stir in the curry powder, then pour in the coconut milk and season with salt and pepper.','Bring to a gentle boil, turn the heat to low and simmer for 30–35 minutes, until the chicken is tender and cooked through (74°C). Do not let it boil hard. Serve hot.']::text[],NULL,'https://www.facebook.com/groups/749542106307590',10,40,'6','chef','Eyal Shani',ARRAY['Dinner','International','Chicken','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-6','he','עוף בקארי קוקוס',ARRAY['6 חלקי עוף','1 בצל','400 מ"ל חלב קוקוס (פחית)','1 כף אבקת קארי','2 שיני שום','2 כפות שמן','½ כפית מלח','¼ כפית פלפל שחור']::text[],ARRAY['קוצצים בצל ושום.','מחממים את השמן בסיר רחב ומשחימים מעט את חלקי העוף. מוסיפים בצל ושום ומערבבים עד ריכוך. שוטפים ידיים אחרי מגע בעוף נא.','מוסיפים את הקארי ומערבבים, יוצקים את חלב הקוקוס ומתבלים במלח ופלפל.','מביאים לרתיחה עדינה, מנמיכים לאש נמוכה ומבשלים 30–35 דקות, עד שהעוף רך ומבושל לגמרי (74°C). לא להרתיח חזק. מגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-6','ru','Курица карри с кокосовым молоком',ARRAY['6 кусков курицы','1 луковица','400 мл консервированного кокосового молока','1 ст. л. порошка карри','2 зубчика чеснока','2 ст. л. масла','½ ч. л. соли','¼ ч. л. чёрного перца']::text[],ARRAY['Порубите лук и чеснок.','Разогрейте масло в широкой кастрюле и слегка обжарьте курицу. Добавьте лук и чеснок и помешивайте, пока они не станут мягкими. После сырой курицы вымойте руки.','Вмешайте карри, затем влейте кокосовое молоко, посолите и поперчите.','Доведите до лёгкого кипения, убавьте огонь и тушите 30–35 минут, пока курица не станет мягкой и не приготовится полностью (74°C). Не давайте сильно кипеть. Подавайте горячим.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:5-15','Lemon garlic chicken',ARRAY['6 chicken pieces','4 cloves garlic','2 lemons, juiced','2 tbsp olive oil','½ tsp salt','¼ tsp black pepper','1 onion','½ cup water']::text[],ARRAY['Chop the onion and garlic.','Heat the olive oil in a wide pot and lightly brown the chicken pieces. Add the onion and garlic and stir until slightly soft. Wash your hands after handling raw chicken.','Add the lemon juice, salt, pepper and the water.','Cover and cook over low heat for about 40 minutes, until the chicken is tender and cooked through (74°C). Taste, adjust the seasoning and serve hot.']::text[],NULL,'https://www.facebook.com/groups/749542106307590',15,45,'6','chef','Eyal Shani',ARRAY['Dinner','Mediterranean','Chicken','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-15','he','עוף בלימון ושום',ARRAY['6 חלקי עוף','4 שיני שום','מיץ מ-2 לימונים','2 כפות שמן זית','½ כפית מלח','¼ כפית פלפל שחור','1 בצל','½ כוס מים']::text[],ARRAY['קוצצים בצל ושום.','מחממים את שמן הזית בסיר רחב ומשחימים מעט את חלקי העוף. מוסיפים בצל ושום ומערבבים עד ריכוך קל. שוטפים ידיים אחרי מגע בעוף נא.','מוסיפים מיץ לימון, מלח, פלפל ואת המים.','מכסים ומבשלים על אש נמוכה כ-40 דקות, עד שהעוף רך ומבושל לגמרי (74°C). טועמים, מתקנים תיבול ומגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:5-15','ru','Курица с лимоном и чесноком',ARRAY['6 кусков курицы','4 зубчика чеснока','сок 2 лимонов','2 ст. л. оливкового масла','½ ч. л. соли','¼ ч. л. чёрного перца','1 луковица','½ стакана воды']::text[],ARRAY['Порубите лук и чеснок.','Разогрейте оливковое масло в широкой кастрюле и слегка обжарьте курицу. Добавьте лук и чеснок и помешивайте, пока они слегка не размякнут. После сырой курицы вымойте руки.','Добавьте лимонный сок, соль, перец и воду.','Накройте крышкой и тушите на слабом огне около 40 минут, пока курица не станет мягкой и не приготовится полностью (74°C). Попробуйте, досолите по вкусу и подавайте горячим.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:4-1','Beef meatballs in tomato sauce',ARRAY['500 g minced beef','1 onion','1 egg','3 tbsp gluten-free breadcrumbs','4 tomatoes','2 tbsp tomato paste','3 tbsp oil','1 tsp salt','½ tsp black pepper','1 cup water']::text[],ARRAY['Finely chop the onion and chop the tomatoes.','Mix the beef, egg, gluten-free breadcrumbs and half the onion in a bowl, season with half the salt and pepper and shape into even meatballs. Wet hands make this easier. Wash your hands after handling raw meat.','Heat the oil in a wide pot and fry the rest of the onion. Add the tomatoes, tomato paste, the water and the remaining salt and pepper and bring to the boil.','Gently add the meatballs and simmer for about 25 minutes without stirring hard, until they are cooked through with no pink inside (71°C). Serve hot.']::text[],NULL,'https://www.facebook.com/groups/749542106307590',20,30,'4','chef','Eyal Shani',ARRAY['Dinner','Middle Eastern','Beef','Eggs','Gluten-free','Kid friendly']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:4-1','he','קציצות בקר ברוטב עגבניות',ARRAY['500 גרם בשר בקר טחון','1 בצל','1 ביצה','3 כפות פירורי לחם ללא גלוטן','4 עגבניות','2 כפות רסק עגבניות','3 כפות שמן','1 כפית מלח','½ כפית פלפל שחור','1 כוס מים']::text[],ARRAY['קוצצים דק את הבצל וחותכים את העגבניות.','מערבבים בקערה בשר, ביצה, פירורי לחם ללא גלוטן ומחצית מהבצל, מתבלים בחצי מהמלח והפלפל ויוצרים קציצות אחידות. ידיים רטובות מקלות על העבודה. שוטפים ידיים אחרי מגע בבשר נא.','מחממים את השמן בסיר רחב ומטגנים את יתרת הבצל. מוסיפים עגבניות, רסק, את המים ואת יתרת המלח והפלפל ומביאים לרתיחה.','מוסיפים את הקציצות בעדינות ומבשלים כ-25 דקות בלי לערבב חזק, עד שהן מבושלות לגמרי ואין בהן ורוד (71°C). מגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:4-1','ru','Говяжьи тефтели в томатном соусе',ARRAY['500 г говяжьего фарша','1 луковица','1 яйцо','3 ст. л. безглютеновых панировочных сухарей','4 помидора','2 ст. л. томатной пасты','3 ст. л. масла','1 ч. л. соли','½ ч. л. чёрного перца','1 стакан воды']::text[],ARRAY['Мелко порубите лук и нарежьте помидоры.','Смешайте в миске фарш, яйцо, безглютеновые сухари и половину лука, приправьте половиной соли и перца и сформируйте одинаковые тефтели. Удобнее делать это мокрыми руками. После сырого мяса вымойте руки.','Разогрейте масло в широкой кастрюле и обжарьте оставшийся лук. Добавьте помидоры, томатную пасту, воду и оставшиеся соль и перец и доведите до кипения.','Осторожно опустите тефтели и тушите около 25 минут, не перемешивая сильно, пока они не приготовятся полностью и внутри не останется розового (71°C). Подавайте горячими.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:6-1','Hungarian beef goulash',ARRAY['1 kg stewing beef','2 large onions','2 carrots','2 potatoes','3 tbsp sweet paprika','3 tbsp oil','2 cloves garlic','1 tsp salt','½ tsp black pepper','1 l water']::text[],ARRAY['Cut the beef into cubes and chop the onions. Cut the carrots and potatoes into chunks. Wash your hands after handling raw meat.','Heat the oil in a large pot and fry the onions until golden. Add the garlic and stir.','Add the beef and brown it on all sides. Stir in the paprika, salt and pepper, then add enough water to come partway up the meat.','Cover and simmer for about 1½ hours.','Add the carrots and potatoes and cook for about 30 minutes more, until the meat and vegetables are completely tender. It tastes even better the next day.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',20,120,'6','chef','Eyal Shani',ARRAY['Dinner','Eastern European','Beef','Potatoes','Gluten-free','Dairy-free','Batch cooking']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:6-1','he','גולאש בקר הונגרי',ARRAY['1 ק"ג בשר בקר לתבשיל','2 בצלים גדולים','2 גזרים','2 תפוחי אדמה','3 כפות פפריקה מתוקה','3 כפות שמן','2 שיני שום','1 כפית מלח','½ כפית פלפל שחור','1 ליטר מים']::text[],ARRAY['חותכים את הבשר לקוביות וקוצצים את הבצל. חותכים את הגזרים ותפוחי האדמה לחתיכות. שוטפים ידיים אחרי מגע בבשר נא.','מחממים את השמן בסיר גדול ומטגנים את הבצל עד הזהבה. מוסיפים שום ומערבבים.','מוסיפים את קוביות הבשר וצורבים מכל הצדדים. מוסיפים פפריקה, מלח ופלפל ומוסיפים מים לכיסוי חלקי של הבשר.','מכסים ומבשלים כשעה וחצי.','מוסיפים את הגזרים ותפוחי האדמה וממשיכים לבשל כ-30 דקות, עד שהבשר והירקות רכים לגמרי. למחרת זה טעים עוד יותר.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:6-1','ru','Венгерский гуляш из говядины',ARRAY['1 кг говядины для тушения','2 крупные луковицы','2 моркови','2 картофелины','3 ст. л. сладкой паприки','3 ст. л. масла','2 зубчика чеснока','1 ч. л. соли','½ ч. л. чёрного перца','1 л воды']::text[],ARRAY['Нарежьте говядину кубиками и порубите лук. Нарежьте морковь и картофель крупными кусками. После сырого мяса вымойте руки.','Разогрейте масло в большой кастрюле и обжарьте лук до золотистого цвета. Добавьте чеснок и перемешайте.','Добавьте говядину и обжарьте со всех сторон. Вмешайте паприку, соль и перец, затем влейте воду так, чтобы она частично покрывала мясо.','Накройте крышкой и тушите около 1½ часа.','Добавьте морковь и картофель и готовьте ещё около 30 минут, пока мясо и овощи не станут совсем мягкими. На следующий день гуляш ещё вкуснее.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:7-1','Stuffed peppers',ARRAY['6 large peppers','500 g minced beef','1 cup rice','1 onion','4 tomatoes','2 tbsp tomato paste','3 tbsp oil','1 tsp salt','½ tsp black pepper','1 cup water']::text[],ARRAY['Wash the peppers, cut off the tops and carefully remove the seeds. Finely chop the onion.','Mix the beef, rice and onion in a bowl and season with half the salt and pepper. Fill the peppers, leaving some room for the rice to swell. Wash your hands after handling raw meat.','Stand the peppers in a wide pot. Grate or chop the tomatoes and mix them with the tomato paste, oil, the water and the remaining salt and pepper.','Pour the sauce over the peppers, cover and simmer over low heat for about 1 hour, until the rice is tender and the filling is cooked through (71°C). Serve hot.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',30,60,'6','chef','Eyal Shani',ARRAY['Dinner','Middle Eastern','Beef','Rice','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:7-1','he','פלפלים ממולאים',ARRAY['6 פלפלים גדולים','500 גרם בשר בקר טחון','1 כוס אורז','1 בצל','4 עגבניות','2 כפות רסק עגבניות','3 כפות שמן','1 כפית מלח','½ כפית פלפל שחור','1 כוס מים']::text[],ARRAY['שוטפים את הפלפלים, מסירים את החלק העליון ומרוקנים בזהירות את הגרעינים. קוצצים דק את הבצל.','מערבבים בקערה בשר, אורז ובצל ומתבלים בחצי מהמלח והפלפל. ממלאים את הפלפלים, לא עד הסוף, כדי שהאורז יוכל לתפוח. שוטפים ידיים אחרי מגע בבשר נא.','מסדרים את הפלפלים בסיר רחב. מגררים או קוצצים את העגבניות ומערבבים עם הרסק, השמן, המים ויתרת המלח והפלפל.','יוצקים את הרוטב על הפלפלים, מכסים ומבשלים על אש נמוכה כשעה, עד שהאורז רך והמילוי מבושל לגמרי (71°C). מגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:7-1','ru','Фаршированные перцы',ARRAY['6 крупных сладких перцев','500 г говяжьего фарша','1 стакан риса','1 луковица','4 помидора','2 ст. л. томатной пасты','3 ст. л. масла','1 ч. л. соли','½ ч. л. чёрного перца','1 стакан воды']::text[],ARRAY['Вымойте перцы, срежьте верхушки и аккуратно удалите семена. Мелко порубите лук.','Смешайте в миске фарш, рис и лук и приправьте половиной соли и перца. Наполните перцы, оставляя место, чтобы рис мог набухнуть. После сырого мяса вымойте руки.','Поставьте перцы в широкую кастрюлю. Натрите или нарежьте помидоры и смешайте с томатной пастой, маслом, водой и оставшимися солью и перцем.','Залейте перцы соусом, накройте крышкой и тушите на слабом огне около часа, пока рис не станет мягким, а начинка не приготовится полностью (71°C). Подавайте горячими.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:10-1','Chraime fish stew',ARRAY['800 g white fish fillets','4 tomatoes, grated','2 tbsp tomato paste','6 cloves garlic','3 tbsp olive oil','1 tsp sweet paprika','1 tsp hot paprika','½ tsp ground cumin','½ tsp salt','¼ tsp black pepper','2 tbsp chopped coriander','1 cup water']::text[],ARRAY['Heat the oil in a wide pot and fry the garlic lightly.','Add the grated tomatoes, tomato paste, both paprikas, cumin, salt, pepper and the water. Simmer for 10–15 minutes, until the sauce thickens.','Lay the fish in the sauce, cover and cook for about 15 minutes without stirring, until the fish is opaque and flakes easily.','Scatter with coriander and serve hot.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',15,30,'4','chef','Eyal Shani',ARRAY['Dinner','North African','Fish','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:10-1','he','חריימה קלאסי',ARRAY['800 גרם פילה דג לבן','4 עגבניות מגוררות','2 כפות רסק עגבניות','6 שיני שום','3 כפות שמן זית','1 כפית פפריקה מתוקה','1 כפית פפריקה חריפה','½ כפית כמון','½ כפית מלח','¼ כפית פלפל שחור','2 כפות כוסברה קצוצה','1 כוס מים']::text[],ARRAY['מחממים את השמן בסיר רחב ומטגנים את השום קלות.','מוסיפים את העגבניות המגוררות, רסק העגבניות, שני סוגי הפפריקה, הכמון, המלח, הפלפל והמים. מבשלים 10–15 דקות, עד שהרוטב מסמיך.','מסדרים את הדגים ברוטב, מכסים ומבשלים כ-15 דקות בלי לערבב, עד שהדג אטום ומתפרק בקלות.','מפזרים כוסברה ומגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:10-1','ru','Хрейме — рыба в остром томатном соусе',ARRAY['800 г филе белой рыбы','4 помидора, натёртых на тёрке','2 ст. л. томатной пасты','6 зубчиков чеснока','3 ст. л. оливкового масла','1 ч. л. сладкой паприки','1 ч. л. острой паприки','½ ч. л. молотого кумина','½ ч. л. соли','¼ ч. л. чёрного перца','2 ст. л. рубленой кинзы','1 стакан воды']::text[],ARRAY['Разогрейте масло в широкой кастрюле и слегка обжарьте чеснок.','Добавьте тёртые помидоры, томатную пасту, обе паприки, кумин, соль, перец и воду. Тушите 10–15 минут, пока соус не загустеет.','Выложите рыбу в соус, накройте крышкой и готовьте около 15 минут, не перемешивая, пока рыба не станет непрозрачной и не будет легко разделяться на волокна.','Посыпьте кинзой и подавайте горячим.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:10-3','Oven-baked salmon',ARRAY['4 salmon fillets','2 tbsp olive oil','1 lemon, juiced','2 cloves garlic','½ tsp salt','¼ tsp black pepper','2 tbsp chopped parsley','1 tsp dried oregano']::text[],ARRAY['Heat the oven to 200°C. Place the salmon in a baking dish.','Mix the oil and lemon juice with the crushed garlic, salt, pepper and oregano. Pour over the salmon and scatter with parsley.','Bake for about 15 minutes, until the salmon is opaque and flakes easily (63°C). Do not overbake.','Serve straight away.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',10,15,'4','chef','Eyal Shani',ARRAY['Dinner','Mediterranean','Fish','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:10-3','he','סלמון בתנור',ARRAY['4 נתחי סלמון','2 כפות שמן זית','מיץ מלימון אחד','2 שיני שום','½ כפית מלח','¼ כפית פלפל שחור','2 כפות פטרוזיליה קצוצה','1 כפית אורגנו יבש']::text[],ARRAY['מחממים תנור ל-200 מעלות. מניחים את הסלמון בתבנית.','מערבבים שמן ומיץ לימון עם שום כתוש, מלח, פלפל ואורגנו. יוצקים על הסלמון ומפזרים פטרוזיליה.','אופים כ-15 דקות, עד שהסלמון אטום ומתפרק בקלות (63°C). לא לאפות יתר על המידה.','מגישים מיד.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:10-3','ru','Лосось в духовке',ARRAY['4 куска филе лосося','2 ст. л. оливкового масла','сок 1 лимона','2 зубчика чеснока','½ ч. л. соли','¼ ч. л. чёрного перца','2 ст. л. рубленой петрушки','1 ч. л. сушёного орегано']::text[],ARRAY['Разогрейте духовку до 200°C. Выложите лосось в форму для запекания.','Смешайте масло и лимонный сок с измельчённым чесноком, солью, перцем и орегано. Полейте лосося и посыпьте петрушкой.','Запекайте около 15 минут, пока лосось не станет непрозрачным и не будет легко разделяться на волокна (63°C). Не передерживайте.','Подавайте сразу.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:11-8','Chicken and rice stir-fry',ARRAY['400 g chicken breast','2 cups cooked rice','1 carrot','1 red pepper','1 onion','2 cloves garlic','2 tbsp oil','3 tbsp gluten-free soy sauce','1 tsp grated ginger','¼ tsp salt','¼ tsp black pepper','2 spring onions']::text[],ARRAY['Cut the chicken into cubes. Cut the carrot, red pepper and onion into thin strips and chop the garlic and spring onions. Have everything ready before you start. Wash your hands and board after handling raw chicken.','Heat a large frying pan or wok over high heat, add the oil and stir-fry the chicken until golden and cooked through (74°C).','Add the onion, carrot and red pepper and stir-fry for 3–4 minutes, then add the garlic and ginger.','Add the rice and soy sauce, season with salt and pepper and stir until steaming hot. Cold rice cooked the day before works best. Scatter with spring onions and serve hot.']::text[],'data:image/jpeg;base64,','https://www.facebook.com/groups/749542106307590',10,15,'4','chef','Eyal Shani',ARRAY['Dinner','Chinese','Chicken','Rice','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:11-8','he','מוקפץ עוף ואורז',ARRAY['400 גרם חזה עוף','2 כוסות אורז מבושל','1 גזר','1 פלפל אדום','1 בצל','2 שיני שום','2 כפות שמן','3 כפות רוטב סויה ללא גלוטן','1 כפית ג''ינג''ר מגורר','¼ כפית מלח','¼ כפית פלפל שחור','2 גבעולי בצל ירוק']::text[],ARRAY['חותכים את העוף לקוביות. חותכים את הגזר, הפלפל והבצל לרצועות דקות וקוצצים שום ובצל ירוק. מכינים הכול מראש. שוטפים ידיים וקרש אחרי מגע בעוף נא.','מחממים מחבת גדולה או ווק על אש גבוהה, מוסיפים שמן ומקפיצים את העוף עד הזהבה ובישול מלא (74°C).','מוסיפים בצל, גזר ופלפל ומקפיצים 3–4 דקות, ואז מוסיפים שום וג''ינג''ר.','מוסיפים את האורז ורוטב הסויה, מתבלים במלח ופלפל ומערבבים עד שהכול חם מאוד. אורז קר שבושל יום קודם מתאים במיוחד. מפזרים בצל ירוק ומגישים חם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:11-8','ru','Жареный рис с курицей',ARRAY['400 г куриной грудки','2 стакана варёного риса','1 морковь','1 красный сладкий перец','1 луковица','2 зубчика чеснока','2 ст. л. масла','3 ст. л. безглютенового соевого соуса','1 ч. л. тёртого имбиря','¼ ч. л. соли','¼ ч. л. чёрного перца','2 стебля зелёного лука']::text[],ARRAY['Нарежьте курицу кубиками. Нарежьте морковь, перец и лук тонкой соломкой, порубите чеснок и зелёный лук. Подготовьте всё заранее. После сырой курицы вымойте руки и доску.','Сильно разогрейте большую сковороду или вок, добавьте масло и обжарьте курицу, помешивая, до золотистого цвета и полной готовности (74°C).','Добавьте лук, морковь и перец и жарьте 3–4 минуты, затем добавьте чеснок и имбирь.','Добавьте рис и соевый соус, посолите, поперчите и перемешивайте, пока всё не прогреется до горячего пара. Лучше всего подходит холодный рис, сваренный накануне. Посыпьте зелёным луком и подавайте горячим.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:8-4','Rice and lentil mujaddara',ARRAY['1 cup green lentils','1½ cups rice','2 large onions','3 tbsp oil','1 tsp salt','½ tsp black pepper','3 cups water']::text[],ARRAY['Rinse the lentils, cook them in boiling water for 10 minutes until partly soft, and drain.','Slice the onions and fry them in the oil in a pot until deep golden. Lift out about half of the onions and set them aside.','Rinse the rice and add it to the pot with the lentils, salt, pepper and the water. Bring to the boil.','Cover and cook over low heat for about 20 minutes, until the rice and lentils are tender. Scatter with the set-aside onions and serve.']::text[],NULL,'https://www.facebook.com/groups/749542106307590',10,35,'4','chef','Eyal Shani',ARRAY['Dinner','Middle Eastern','Rice','Vegetarian','Vegan','Gluten-free','Dairy-free','Budget']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:8-4','he','מג''דרה עדשים',ARRAY['1 כוס עדשים ירוקות','1½ כוסות אורז','2 בצלים גדולים','3 כפות שמן','1 כפית מלח','½ כפית פלפל שחור','3 כוסות מים']::text[],ARRAY['שוטפים את העדשים, מבשלים אותן במים רותחים 10 דקות עד שהן רכות חלקית, ומסננים.','פורסים את הבצלים ומטגנים אותם בשמן בסיר עד הזהבה עמוקה. מוציאים כמחצית מהבצל ושומרים בצד.','שוטפים את האורז ומוסיפים לסיר עם העדשים, המלח, הפלפל והמים. מביאים לרתיחה.','מכסים ומבשלים על אש נמוכה כ-20 דקות, עד שהאורז והעדשים רכים. מפזרים את הבצל ששמרנו ומגישים.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:8-4','ru','Маджадра — рис с чечевицей',ARRAY['1 стакан зелёной чечевицы','1½ стакана риса','2 крупные луковицы','3 ст. л. масла','1 ч. л. соли','½ ч. л. чёрного перца','3 стакана воды']::text[],ARRAY['Промойте чечевицу, отварите в кипящей воде 10 минут до полуготовности и слейте воду.','Нарежьте лук полукольцами и обжарьте в масле в кастрюле до тёмно-золотистого цвета. Отложите примерно половину лука.','Промойте рис и добавьте его в кастрюлю вместе с чечевицей, солью, перцем и водой. Доведите до кипения.','Накройте крышкой и готовьте на слабом огне около 20 минут, пока рис и чечевица не станут мягкими. Посыпьте отложенным луком и подавайте.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language) VALUES ('tablewise:catalog:gf-basic:9-5','Roasted cauliflower with tahini sauce',ARRAY['1 large cauliflower','3 tbsp olive oil','½ tsp salt','¼ tsp black pepper','½ cup raw tahini','¼ cup water','½ lemon, juiced','1 clove garlic','2 tbsp chopped parsley']::text[],ARRAY['Heat the oven to 200°C. Break the cauliflower into florets, toss with the oil, salt and pepper and spread on a baking tray.','Roast for 25–30 minutes, until golden.','Meanwhile, stir the water into the tahini a little at a time, then add the lemon juice and crushed garlic and whisk to a smooth sauce.','Arrange the cauliflower on a plate, pour the tahini sauce over it and scatter with parsley.']::text[],NULL,'https://www.facebook.com/groups/749542106307590',10,30,'4','chef','Eyal Shani',ARRAY['Dinner','Middle Eastern','Vegetarian','Vegan','Gluten-free','Dairy-free']::text[],'en') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,image=COALESCE(EXCLUDED.image,recipes.image),source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=NULL,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:9-5','he','כרובית ברוטב טחינה',ARRAY['1 כרובית גדולה','3 כפות שמן זית','½ כפית מלח','¼ כפית פלפל שחור','½ כוס טחינה גולמית','¼ כוס מים','מיץ מחצי לימון','1 שן שום','2 כפות פטרוזיליה קצוצה']::text[],ARRAY['מחממים תנור ל-200 מעלות. מפרקים את הכרובית לפרחים, מערבבים עם השמן, המלח והפלפל ומסדרים בתבנית.','אופים 25–30 דקות, עד הזהבה.','בינתיים מוסיפים את המים לטחינה בהדרגה, מוסיפים מיץ לימון ושום כתוש וטורפים לרוטב חלק.','מסדרים את הכרובית בצלחת, יוצקים מעל את רוטב הטחינה ומפזרים פטרוזיליה.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:gf-basic:9-5','ru','Запечённая цветная капуста с соусом тахини',ARRAY['1 крупный кочан цветной капусты','3 ст. л. оливкового масла','½ ч. л. соли','¼ ч. л. чёрного перца','½ стакана тахини','¼ стакана воды','сок ½ лимона','1 зубчик чеснока','2 ст. л. рубленой петрушки']::text[],ARRAY['Разогрейте духовку до 200°C. Разберите капусту на соцветия, перемешайте с маслом, солью и перцем и разложите на противне.','Запекайте 25–30 минут до золотистого цвета.','Тем временем понемногу вмешивайте воду в тахини, затем добавьте лимонный сок и измельчённый чеснок и взбейте до гладкого соуса.','Выложите капусту на блюдо, полейте соусом тахини и посыпьте петрушкой.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
